import React, { Fragment, useState } from "react";
import './AddProduct.css';

const AddProduct=()=>{
   const[tshirtName,setTshirtName]=   useState("");
   const[description,setDescription]=   useState("");
   const[price,setPrice]=   useState("");
   const[large,setLarge]=   useState("");
   const[medium,setMedium]=   useState("");
   const[small,setSmall]=   useState("");
   const [submitted, setSubmitted] = useState(false);
  
    const tshirtNameHandler=(event)=>{
        setTshirtName(event.target.value)
    }
    const descHandler=(event)=>{
    setDescription(event.target.value);
    }
    const priceHandler=(event)=>{
        setPrice(event.target.value);
    }
    const largehandler=(event)=>{
        setLarge(event.target.value);
    }
    const mediumHandler=(event)=>{
        setMedium(event.target.value)
    }
    const smallHandler=(event)=>{
        setSmall(event.target.value);
    }

    const addProductHandler=(event)=>{
        event.preventDefault();
        setSubmitted(true);

        // const obj={
        //   tshirtName,
        //   description,
        //   price,
        //   large,
        //   medium,
        //   small,
        // }
       
        // function showUserOnScrren(obj){
        //     const parentElement=document.getElementById('listOfItems');
        //     const childElement= document.createElement('li');
        //     childElement.textContent=obj.candyName+ "-"+ obj.tshirtName +"-" +obj.description+"-"+obj.price +" ";
        //     parentElement.appendChild(childElement);

        //     const buyOneButton=document.createElement('input');
        //     buyOneButton.type="button"
        //     buyOneButton.value='BuyLarge'
        //     buyOneButton.onclick=()=>{
         
        //            if(obj.quantity>0){
        //               obj.quantity -=1;
        //               document.getElementById('quantity').value=obj.quantity-1;
                  
        //               const updatedObj = {
        //                   candyName: obj.candyName,
        //                   descrip: obj.descrip,
        //                   pricefor: obj.pricefor,
        //                   quantity: obj.quantity
        //               };

        //               childElement.appendChild(buyOneButton);
        //               // parentElement.appendChild(childElement);
           
        //                const buyTwoButton=document.createElement('input');
        //                buyTwoButton.type="button"
        //                buyTwoButton.value='BuyMedium'
        //                buyTwoButton.onclick=()=>{
        //                    if(obj.quantity>0){
        //                        obj.quantity -=2;
        //                        document.getElementById('quantity').value=obj.quantity-2;
                           
        //                        const updatedObj = {
        //                            candyName: obj.candyName,
        //                            descrip: obj.descrip,
        //                            pricefor: obj.pricefor,
        //                            quantity: obj.quantity
        //                        };
        //                        childElement.appendChild(buyTwoButton);
        //                        // parentElement.appendChild(childElement);
                    
        //                         const buyThreeButton=document.createElement('input');
        //                         buyThreeButton.type="button"
        //                         buyThreeButton.value='BuySmall'
                    
        //                         buyThreeButton.onclick=()=>{
        //                             if(obj.quantity>0){
        //                                 obj.quantity -=3;
        //                                 document.getElementById('quantity').value=obj.quantity-3;
                                    
        //                                 const updatedObj = {
        //                                     candyName: obj.candyName,
        //                                     descrip: obj.descrip,
        //                                     pricefor: obj.pricefor,
        //                                     quantity: obj.quantity
        //                                 };
        //                                 childElement.appendChild(buyThreeButton);
    }
    return(
      <Fragment>
     
         <form  onsubmit={addProductHandler}>
        <div className="container">
        <div>
            <label htmlFor="name">T-Shirt Name</label> <br></br>
            <input type="text" name="name" id="candyname"value={tshirtName} onChange={tshirtNameHandler}></input>
        </div>

        <div>
            <label htmlFor="desc">Description</label><br></br>
            <input type="text" name="desc" id="desc" value={description} onChange={descHandler}></input>
        </div>
        <div>
            <label htmlFor="price">Price</label><br></br>
            <input type="number" name="price" id="price" value={price} onChange={priceHandler}></input>
        </div>
        <div className="quantity">
            <label htmlFor="quantity">Quantity Avilable</label><br></br>
            <div>
             <label htmlFor="large">L</label>
            <input type="number" name="large" id="large"  value={large} onChange={largehandler}></input>
            </div>
            <div>
                <label htmlFor="medium">M</label>
                <input type="number" name="medium" id="medium" value={medium} onChange={mediumHandler}></input>
            </div>
            <div>
                <label htmlFor="small">S</label>
                <input type="number" name="small" id="small" value={small} onChange={smallHandler}></input>
            </div>
        </div>
         <div>
               <button>AddProduct</button>
        </div>
    </div>
    </form>
    {submitted && (
            <div>
               <h2>{tshirtName}</h2>
               <p>{description}</p>
               <p>Price: {price}</p>
               <button onClick={() => { /* Logic for buying large */ }}>Buy Large</button>
               <button onClick={() => { /* Logic for buying medium */ }}>Buy Medium</button>
               <button onClick={() => { /* Logic for buying small */ }}>Buy Small</button>
            </div>
         )}
    <ul id="listOfItems"></ul>


      </Fragment>
    )
}
export default AddProduct;
